import { jsPDF } from "jspdf";
import logo from "../icons/logo1.png";


export const generatePdf = async (teethList) => {
    const doc = new jsPDF();

    doc.setFontSize(16);
    const base64Image = await convertImgToBase64(logo);
    doc.addImage(base64Image, 'PNG', 15, 10, 30, 30); // imagine în colțul stânga sus
    doc.text("DentalIQ PDF Report", 20, 20);
    doc.setFontSize(12);
    doc.text("This is a dental report.", 20, 30);

    let y = 40;

    // Parcurgem fiecare dinte și îl adăugăm în PDF
    teethList.forEach((tooth, index) => {
        const toothTitle = `Tooth ${tooth.name}`;
        doc.setFont(undefined, "bold");
        doc.text(toothTitle, 20, y);
        y += 8;

        if (tooth.issues && tooth.issues.length > 0) {
            doc.setFont(undefined, "normal");
            tooth.issues.forEach((issue) => {
                doc.text(`- ${issue.name}`, 25, y);
                y += 6;

                // Dacă se ajunge prea jos în pagină, adaugă pagină nouă
                if (y > 270) {
                    doc.addPage();
                    y = 20;
                }
            });
        } else {
            doc.setFont(undefined, "normal");
            doc.text("- No issues identified", 25, y);
            y += 6;
        }

        y += 4;
    });

    const pdfBlob = doc.output("blob");
    const blobUrl = URL.createObjectURL(pdfBlob);
    window.open(blobUrl); // Deschide PDF în alt tab
};

// Convertor pentru fișier importat
const convertImgToBase64FromImport = (imgPath) => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.src = imgPath;

        img.onload = () => {
            const canvas = document.createElement("canvas");
            canvas.width = img.width;
            canvas.height = img.height;

            const ctx = canvas.getContext("2d");
            ctx.drawImage(img, 0, 0);

            const dataUrl = canvas.toDataURL("image/png");
            resolve(dataUrl);
        };

        img.onerror = (err) => reject("Failed to load image");
    });
};
